import { Table } from '../../types';

export const generateWordPressPlugin = (
  pluginName: string,
  tables: Table[]
): Record<string, string> => {
  const files: Record<string, string> = {};
  const slug = pluginName.toLowerCase().replace(/\s+/g, '-');

  // Main Plugin File
  files[`${slug}/${slug}.php`] = `<?php
/**
 * Plugin Name: ${pluginName}
 * Description: Enterprise WordPress Plugin with CPTs, Custom $wpdb Tables & Gutenberg Blocks
 * Version: 1.0.0
 * Author: Generated by AI Studio Enterprise Engine
 */

if (!defined('ABSPATH')) exit;

register_activation_hook(__FILE__, '${slug}_install_db');

function ${slug}_install_db() {
    global $wpdb;
    $charset_collate = $wpdb->get_charset_collate();

    ${tables
      .map(
        (t) => `
    $table_${t.name.toLowerCase()} = $wpdb->prefix . '${t.name.toLowerCase()}s';
    $sql_${t.name.toLowerCase()} = "CREATE TABLE $table_${t.name.toLowerCase()} (
        id bigint(20) NOT NULL AUTO_INCREMENT,
        ${(t.fields || []).map((c) => `${c.name} varchar(255) DEFAULT '' NOT NULL`).join(',\n        ')},
        PRIMARY KEY  (id)
    ) $charset_collate;";
    require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
    dbDelta($sql_${t.name.toLowerCase()});
`
      )
      .join('\n')}
}

// REST API Endpoints
add_action('rest_api_init', function () {
    register_rest_route('${slug}/v1', '/data', array(
        'methods' => 'GET',
        'callback' => function() {
            return new WP_REST_Response(array('status' => 'success', 'plugin' => '${pluginName}'), 200);
        },
        'permission_callback' => '__return_true'
    ));
});
`;

  return files;
};

export const generateNextcloudApp = (
  appName: string,
  tables: Table[]
): Record<string, string> => {
  const files: Record<string, string> = {};
  const appId = appName.toLowerCase().replace(/\s+/g, '_');

  files[`${appId}/appinfo/info.xml`] = `<?xml version="1.0" encoding="UTF-8"?>
<info xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="https://plugin.nextcloud.com/schema/info.xsd">
    <id>${appId}</id>
    <name>${appName}</name>
    <description>Enterprise Nextcloud OCP App</description>
    <version>1.0.0</version>
    <licence>agpl</licence>
    <dependencies>
        <nextcloud min-version="28" max-version="30"/>
    </dependencies>
</info>`;

  files[`${appId}/lib/Controller/PageController.php`] = `<?php

namespace OCA\\${appName.replace(/\s+/g, '')}\\Controller;

use OCP\\AppFramework\\Controller;
use OCP\\AppFramework\\Http\\TemplateResponse;
use OCP\\IRequest;

class PageController extends Controller {
    public function __construct(string $appName, IRequest $request) {
        parent::__construct($appName, $request);
    }

    /**
     * @NoAdminRequired
     * @NoCSRFRequired
     */
    public function index(): TemplateResponse {
        return new TemplateResponse($this->appName, 'main');
    }
}`;

  return files;
};
